import assert from 'node:assert/strict';
import { test } from 'node:test';
import { handle } from '../src/app.ts';
import { createContext, forkContext } from '../src/context-factory.ts';
import { describeJob } from '../src/jobs.ts';
import { auditLabel } from '../src/job-types.ts';
import { traceSummary } from '../src/plugins/index.ts';
import { record0 } from '../src/catalog/record0.ts';

test('end-to-end propagation and context fields', () => {
  const job = { requestId: 'job-xyz', name: 'data-sync' };
  const result = handle('trace-123', 'user-abc', job);

  // Context field is traceId, no requestId compatibility member
  assert.equal(result.context.traceId, 'trace-123');
  assert.equal('requestId' in result.context, false);
  assert.equal(result.context.userId, 'user-abc');

  // Headers output
  assert.deepEqual(result.headers, { 'x-request-id': 'trace-123' });

  // Logs output (wire/output key requestId preserved)
  assert.deepEqual(result.logs, { requestId: 'trace-123', userId: 'user-abc' });

  // Response body and worker fork propagation
  assert.equal(result.body.requestId, 'trace-123');
  assert.deepEqual(result.body.payload, {
    requestId: 'job-xyz',
    trace: 'trace-123/worker',
    audit: 'job:job-xyz',
    name: 'data-sync'
  });
});

test('context-factory non-mutation and forkContext suffixes', () => {
  const ctx = createContext('trace-base', 'user-42');
  assert.equal(ctx.traceId, 'trace-base');
  assert.equal(ctx.userId, 'user-42');
  assert.equal('requestId' in ctx, false);

  const forked = forkContext(ctx, 'stage-1');
  assert.equal(forked.traceId, 'trace-base/stage-1');
  assert.equal(forked.userId, 'user-42');
  assert.equal('requestId' in forked, false);

  // Non-mutation of original context
  assert.equal(ctx.traceId, 'trace-base');

  const forked2 = forkContext(forked, 'substage');
  assert.equal(forked2.traceId, 'trace-base/stage-1/substage');
  assert.equal('requestId' in forked2, false);
});

test('unrelated Job.requestId and auditLabel remain intact', () => {
  const job = { requestId: 'job-spec-1', name: 'indexer' };
  assert.equal(job.requestId, 'job-spec-1');
  assert.equal(auditLabel('job-spec-1'), 'job:job-spec-1');

  const ctx = createContext('trace-999', 'user-00');
  const described = describeJob(job, ctx);
  assert.deepEqual(described, {
    requestId: 'job-spec-1',
    trace: 'trace-999',
    audit: 'job:job-spec-1',
    name: 'indexer'
  });
});

test('plugins traceSummary and plugin outputs preserved', () => {
  const ctx = createContext('trace-plugin-test', 'user-p');
  const summary = traceSummary(ctx);
  assert.equal(summary.length, 8);
  for (let i = 0; i < 8; i++) {
    assert.deepEqual(summary[i], {
      requestId: 'trace-plugin-test',
      tag: `plugin${i}`,
      user: 'user-p'
    });
  }
});

test('catalog RequestContext and requestId remain unchanged', () => {
  const catCtx = { requestId: 'cat-item-1', category: 'electronics' };
  const res = record0(catCtx);
  assert.deepEqual(res, {
    requestId: 'cat-item-1',
    category: 'electronics',
    label: 'record0:cat-item-1'
  });
});

